Nat4	loadPersistents_List_20_HIView(V_Environment environment);
Nat4	loadPersistents_List_20_HIView(V_Environment environment)
{
	V_Value tempPersistent = NULL;
	V_Dictionary dictionary = environment->persistentsTable;

	tempPersistent = create_persistentNode("HIVPL List View/HIObject Class",tempPersistent_HIVPL_20_List_20_View_2F_HIObject_20_Class,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("HIVPL List View/Control Kind",tempPersistent_HIVPL_20_List_20_View_2F_Control_20_Kind,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("HIVPL List Item/HIObject Class",tempPersistent_HIVPL_20_List_20_Item_2F_HIObject_20_Class,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("HIVPL List Item/Control Kind",tempPersistent_HIVPL_20_List_20_Item_2F_Control_20_Kind,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("HIVPL List Window/Toolbar",tempPersistent_HIVPL_20_List_20_Window_2F_Toolbar,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("HIVPL Graphic Item/HIObject Class",tempPersistent_HIVPL_20_Graphic_20_Item_2F_HIObject_20_Class,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("HIVPL Graphic Item/Control Kind",tempPersistent_HIVPL_20_Graphic_20_Item_2F_Control_20_Kind,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("HIVPL Dynamic Text/HIObject Class",tempPersistent_HIVPL_20_Dynamic_20_Text_2F_HIObject_20_Class,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	tempPersistent = create_persistentNode("HIVPL Dynamic Text/Control Kind",tempPersistent_HIVPL_20_Dynamic_20_Text_2F_Control_20_Kind,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	return kNOERROR;

}

Nat4	load_List_20_HIView(V_Environment environment);
Nat4	load_List_20_HIView(V_Environment environment)
{

	loadClasses_List_20_HIView(environment);
	loadUniversals_List_20_HIView(environment);
	loadPersistents_List_20_HIView(environment);
	return kNOERROR;

}

